def build():
    questions, bad = [], []
    passages = [{"key": "T1", "title": TABLE[0], "text": TABLE[1]},
                {"key": "L4", "title": POEM3[0], "text": POEM3[1]}, {"key": "L5", "title": DRAMA[0], "text": DRAMA[1]}]
    for key, diff, q, a, b, c, d, ans, exp in ECON_T:
        questions.append({"subject": "Economics", "topic": "Price Determination", "passage": key, "difficulty": diff, "q": q, "A": a, "B": b, "C": c, "D": d, "answer": ans, "explanation": exp})
    for subject, rows in (("Economics", ECON), ("Commerce", COMM)):
        for topic, diff, q, a, b, c, d, ans, exp, verify in rows:
            item = {"subject": subject, "topic": topic, "difficulty": diff, "q": q, "A": a, "B": b, "C": c, "D": d, "answer": ans, "explanation": exp}
            if verify:
                expected = eval(verify, {"math": math})
                got = _num(item[ans])
                if got is None or abs(got - expected) > max(0.01 * abs(expected), 0.006):
                    bad.append((q[:60], ans, item[ans], expected))
            questions.append(item)
    for key, diff, q, a, b, c, d, ans, exp in LIT_P:
        questions.append({"subject": "Literature in English", "topic": "Literary Appreciation", "passage": key, "difficulty": diff, "q": q, "A": a, "B": b, "C": c, "D": d, "answer": ans, "explanation": exp})
    for subject, rows in (("Government", GOVT), ("Literature in English", LIT), ("Christian Religious Studies", CRS), ("Islamic Religious Studies", IRS)):
        for topic, diff, q, a, b, c, d, ans, exp in rows:
            questions.append({"subject": subject, "topic": topic, "difficulty": diff, "q": q, "A": a, "B": b, "C": c, "D": d, "answer": ans, "explanation": exp})
    if bad:
        for b_ in bad:
            print("MISMATCH:", b_)
        sys.exit("Verification failed — file not written.")
    apply_fixes(questions)
    _balance(questions)
    texts = [x["q"] for x in questions]
    assert len(texts) == len(set(texts)), "duplicate question text"
    assert all(x["answer"] in "ABCD" and all(x[k] for k in "ABCD") for x in questions)
    batch = {
        "batch_id": "batch_008_arts_round2",
        "exam_type": "JAMB",
        "note": "Round 2 for Economics (with a demand/supply schedule), Government, Commerce, Literature (third unseen poem + drama extract + set-text items), CRS and IRS.",
        "passages": passages,
        "questions": questions,
        "deactivate": [],
    }
    with open(OUT, "w", encoding="utf-8") as fh:
        json.dump(batch, fh, ensure_ascii=False, indent=1)
    from collections import Counter
    print(f"wrote {OUT}: {len(questions)} questions, {len(passages)} passages")
    print("answer letters:", dict(Counter(x['answer'] for x in questions)))
    print("per subject:", dict(Counter(x['subject'] for x in questions)))


if __name__ == "__main__":
    build()
